// Minimal shim of the automatic JSX runtime. zcompiler lowers `<Badge x={1}/>`
// to `jsx(Badge, { x: 1 })` and INJECTS the import of this module; it is
// therefore a real project dependency, external to the bundle (bare specifier).
export const jsx = (type, props) => ({ type, props });
export const jsxs = jsx;
export const Fragment = 'fragment';
